  up:[100.8,100.3,99.2,98.8,99.5,98.1,97.4,98.2,97.1,96.5,97.2,96.2,95.8,96.4,95.3,94.9,95.7,95.1],down:[102.4,103.1,102.8,104,104.8,104.2,105.3,106.1,105.5,106.8,107.6,107,108.2,109,108.4,109.5,110.2,109.8],
